"const cleanPreOrderDate = (dateVal) => {
  if (!dateVal) return getCurrentDateString();
  let d;
  if (typeof dateVal === 'object' && dateVal instanceof Date) {
    d = dateVal;
  } else {
    const cleanStr = String(dateVal).includes('T') ? String(dateVal).split('T')[0] : String(dateVal);
    d = new Date(cleanStr + 'T00:00');
  }
  if (isNaN(d.getTime())) return getCurrentDateString();
  const year = d.getFullYear();
  const month = String(d.getMonth() + 1).padStart(2, '0');
  const day = String(d.getDate()).padStart(2, '0');
  return `${year}-${month}-${day}`;
};

